public class ClaimLine {

    @Column(name = "label", nullable = false)
    private String label;

    @Column(name = "qty", nullable = false)
    private int qty;

    @Column(name = "unit", nullable = false, precision = 12, scale = 2)
    private BigDecimal unit;

